pageCss:
.subpage-hero {
  background: linear-gradient(135deg, var(--navy-dark) 0%, #1B3A5C 100%);
  padding: 160px 48px 80px;
  text-align: center;
}
.subpage-hero .section-label { color: rgba(255,255,255,0.5); }
.subpage-hero h1 {
  font-size: clamp(28px, 5vw, 52px);
  font-weight: 900;
  color: var(--white);
  letter-spacing: -0.03em;
  line-height: 1.08;
  margin-bottom: 24px;
  max-width: 900px;
  margin-left: auto;
  margin-right: auto;
}
.subpage-hero p {
  font-size: 17px;
  color: rgba(255,255,255,0.65);
  max-width: 640px;
  margin: 0 auto 20px;
  line-height: 1.65;
}
.subpage-hero p strong { color: var(--white); font-weight: 700; }
.hero-ctas {
  display: flex;
  justify-content: center;
  flex-wrap: wrap;
  gap: 12px;
  margin: 32px auto 24px;
}
.hero-download {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  background: var(--red);
  color: var(--white);
  padding: 14px 28px;
  border-radius: var(--radius);
  font-size: 15px;
  font-weight: 700;
  letter-spacing: 0.01em;
  transition: background 0.2s;
}
.hero-download:hover { background: var(--red-light); }
.hero-secondary {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  border: 1px solid rgba(255,255,255,0.35);
  color: var(--white);
  padding: 14px 28px;
  border-radius: var(--radius);
  font-size: 15px;
  font-weight: 700;
  letter-spacing: 0.01em;
  transition: background 0.2s, border-color 0.2s;
}
.hero-secondary:hover { background: rgba(255,255,255,0.1); border-color: rgba(255,255,255,0.6); }
.hero-provenance {
  font-size: 13px !important;
  color: rgba(255,255,255,0.45) !important;
  max-width: 560px;
}

.briefing-body {
  background: var(--white);
  padding: 80px 48px;
}
.briefing-inner {
  max-width: 780px;
  margin: 0 auto;
}

.release-meta {
  display: flex;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
  margin-bottom: 48px;
  padding-bottom: 32px;
  border-bottom: 1px solid var(--gray-200);
}
.release-badge {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  background: var(--navy-dark);
  color: var(--white);
  padding: 5px 12px;
  border-radius: 4px;
}
.release-badge-status {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  background: #c0392b;
  color: var(--white);
  padding: 5px 12px;
  border-radius: 4px;
}
.release-date {
  font-size: 14px;
  color: var(--gray-400);
}
.release-author {
  font-size: 14px;
  font-weight: 700;
  color: var(--navy);
}

.acknowledgment {
  background: var(--cream);
  border: 2px solid var(--navy);
  border-radius: var(--radius-lg);
  padding: 32px 36px;
  margin-bottom: 8px;
  box-shadow: 0 4px 20px rgba(27,47,78,0.08);
}
.acknowledgment-label {
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--navy);
  margin-bottom: 14px;
  display: flex;
  align-items: center;
  gap: 10px;
}
.acknowledgment-label::after {
  content: '';
  flex: 1;
  height: 1px;
  background: rgba(27,47,78,0.2);
}
.acknowledgment p {
  margin-bottom: 14px !important;
  font-size: 16px !important;
  color: var(--navy-dark) !important;
  line-height: 1.75 !important;
}
.acknowledgment p:first-of-type {
  font-size: 18px !important;
  font-weight: 600;
  line-height: 1.6 !important;
}
.acknowledgment p:last-child { margin-bottom: 0 !important; }

.briefing-inner h2 {
  font-size: clamp(20px, 3vw, 26px);
  font-weight: 800;
  color: var(--navy-dark);
  letter-spacing: -0.02em;
  margin: 56px 0 20px;
  padding-top: 8px;
  border-top: 3px solid var(--red);
}
.briefing-inner h3 {
  font-size: 18px;
  font-weight: 700;
  color: var(--navy-dark);
  margin: 32px 0 12px;
}
.briefing-inner p {
  font-size: 16px;
  color: var(--gray-600);
  line-height: 1.8;
  margin-bottom: 16px;
}
.briefing-inner ul {
  list-style: none;
  margin: 0 0 20px;
  padding: 0;
}
.briefing-inner ul li {
  font-size: 16px;
  color: var(--gray-600);
  line-height: 1.75;
  padding: 6px 0 6px 24px;
  position: relative;
}
.briefing-inner ul li::before {
  content: "—";
  position: absolute;
  left: 0;
  color: var(--red);
  font-weight: 700;
}

/* STAT GRID */
.stats-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px;
  margin: 28px 0 8px;
}
.stat-card {
  background: var(--gray-50);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg);
  padding: 26px 28px;
}
.stat-card.wide { grid-column: 1 / -1; }
.stat-num {
  font-size: clamp(30px, 5vw, 40px);
  font-weight: 900;
  color: var(--red);
  letter-spacing: -0.03em;
  line-height: 1;
  margin-bottom: 10px;
}
.stat-desc {
  font-size: 14.5px;
  color: var(--gray-600);
  line-height: 1.65;
}
.stat-desc strong { color: var(--navy-dark); }

/* STATUTE QUOTES */
blockquote {
  margin: 24px 0 32px;
  padding: 24px 32px;
  background: var(--cream);
  border-radius: var(--radius-lg);
  border-left: 4px solid var(--navy);
}
blockquote p {
  font-size: 16.5px;
  font-style: italic;
  color: var(--navy-dark);
  line-height: 1.7;
  margin-bottom: 8px !important;
}
blockquote cite {
  font-size: 13px;
  font-style: normal;
  font-weight: 600;
  color: var(--gray-400);
}
blockquote cite a { color: var(--gray-400); text-decoration: underline; }
blockquote cite a:hover { color: var(--red); }

/* PULL QUOTE */
.pull-quote {
  margin: 36px 0;
  padding: 36px 40px;
  background: var(--navy-dark);
  border-radius: var(--radius-lg);
  text-align: center;
}
.pull-quote p {
  font-family: 'Playfair Display', serif;
  font-size: clamp(22px, 3.5vw, 30px);
  font-weight: 700;
  color: var(--white) !important;
  line-height: 1.4;
  margin-bottom: 10px !important;
}
.pull-quote cite {
  font-size: 13px;
  font-style: normal;
  color: rgba(255,255,255,0.5);
}

.update-note {
  background: var(--gray-50);
  border-left: 4px solid var(--navy);
  border-radius: 0 var(--radius-lg) var(--radius-lg) 0;
  padding: 26px 32px;
  margin: 32px 0;
}
.update-note-label {
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--navy);
  margin-bottom: 12px;
}
.update-note p {
  font-size: 15.5px !important;
  margin-bottom: 12px !important;
}
.update-note p:last-child { margin-bottom: 0 !important; }

.finding-box {
  background: var(--gray-50);
  border-left: 4px solid var(--red);
  border-radius: 0 var(--radius-lg) var(--radius-lg) 0;
  padding: 28px 32px;
  margin: 32px 0;
}
.finding-box h3 {
  margin-top: 0;
  font-size: 16px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--red);
  margin-bottom: 10px;
}
.finding-box p { margin-bottom: 0; font-size: 15px; }

/* OWNERSHIP TABLE */
.own-table {
  width: 100%;
  border-collapse: collapse;
  margin: 24px 0 32px;
  font-size: 15px;
}
.own-table th {
  text-align: left;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--gray-400);
  padding: 10px 16px;
  border-bottom: 2px solid var(--gray-200);
}
.own-table td {
  padding: 16px;
  color: var(--gray-600);
  line-height: 1.6;
  vertical-align: top;
  border-bottom: 1px solid var(--gray-100);
}
.own-table td:first-child {
  font-weight: 600;
  color: var(--navy-dark);
  width: 210px;
}
.own-no {
  display: inline-block;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--red);
  margin-right: 6px;
}

/* FIGURE */
.evidence-figure {
  margin: 32px 0;
}
.evidence-figure img {
  width: 100%;
  height: auto;
  border-radius: var(--radius-lg);
  border: 1px solid var(--gray-200);
  display: block;
}
.evidence-figure figcaption {
  font-size: 13px;
  color: var(--gray-400);
  margin-top: 10px;
  line-height: 1.5;
}

/* TOP 50 TABLE */
.table-scroll {
  max-height: 620px;
  overflow-y: auto;
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg);
  margin: 24px 0;
}
.rank-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 14px;
}
.rank-table th {
  position: sticky;
  top: 0;
  background: var(--navy-dark);
  color: var(--white);
  text-align: left;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 10px 14px;
}
.rank-table td {
  padding: 8px 14px;
  color: var(--gray-600);
  line-height: 1.5;
  border-bottom: 1px solid var(--gray-100);
}
.rank-table td:first-child {
  font-weight: 600;
  color: var(--gray-400);
  width: 60px;
}
.rank-table td:nth-child(3),
.rank-table td:nth-child(4),
.rank-table th:nth-child(3),
.rank-table th:nth-child(4) {
  text-align: right;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.rank-table tr.subtotal td {
  font-weight: 700;
  color: var(--navy-dark);
  background: var(--gray-50);
  border-top: 2px solid var(--gray-200);
}
.table-downloads {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin: 20px 0 8px;
}
.btn-file {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  background: var(--red);
  color: var(--white);
  padding: 12px 24px;
  border-radius: var(--radius);
  font-size: 14px;
  font-weight: 700;
  transition: background 0.2s;
}
.btn-file:hover { background: var(--red-light); }

/* ASKS */
.ask-item { margin-bottom: 28px; }
.ask-item h3 { margin: 0 0 8px; }
.ask-item p { margin-bottom: 0 !important; }

/* JOIN GRID */
.join-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px;
  margin: 28px 0;
}
.join-card {
  background: var(--gray-50);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg);
  padding: 24px 26px;
}
.join-card strong {
  display: block;
  font-size: 15px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--red);
  margin-bottom: 8px;
}
.join-card p {
  font-size: 14.5px !important;
  line-height: 1.7 !important;
  margin-bottom: 0 !important;
}
.join-card a { color: var(--red); font-weight: 600; }
.join-card a:hover { text-decoration: underline; }

.contact-cta {
  background: var(--navy-dark);
  border-radius: var(--radius-lg);
  padding: 40px;
  text-align: center;
  margin-top: 40px;
}
.contact-cta h3 {
  color: var(--white);
  font-size: 22px;
  font-weight: 800;
  letter-spacing: -0.01em;
  margin: 0 0 10px;
}
.contact-cta p {
  color: rgba(255,255,255,0.65) !important;
  font-size: 15px !important;
  max-width: 460px;
  margin: 0 auto 24px !important;
}
.contact-cta .btn-contact {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  background: var(--red);
  color: var(--white);
  padding: 15px 32px;
  border-radius: var(--radius);
  font-size: 16px;
  font-weight: 700;
  transition: background 0.2s;
}
.contact-cta .btn-contact:hover { background: var(--red-light); }

/* Read About This in the Media */
.coverage-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin: 28px 0 40px;
}
.coverage-card {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 20px;
  background: var(--gray-50);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg);
  padding: 20px 24px;
  text-decoration: none;
  transition: box-shadow 0.2s, transform 0.2s;
}
.coverage-card:hover { box-shadow: 0 6px 24px rgba(0,0,0,0.09); transform: translateY(-2px); }
.coverage-top { display: flex; align-items: center; gap: 12px; flex-shrink: 0; }
.coverage-badge {
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--white);
  padding: 4px 8px;
  border-radius: 4px;
  line-height: 1;
  white-space: nowrap;
}
.coverage-date {
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--gray-400);
  white-space: nowrap;
}
.coverage-headline {
  flex: 1;
  font-size: 15.5px;
  font-weight: 700;
  color: var(--navy-dark);
  line-height: 1.45;
  letter-spacing: -0.01em;
}
.coverage-more {
  font-size: 13px;
  font-weight: 700;
  color: var(--red);
  flex-shrink: 0;
}
@media (max-width: 768px) {
  .coverage-card { flex-direction: column; align-items: flex-start; gap: 10px; }
}

@media (max-width: 768px) {
  .subpage-hero { padding: 140px 24px 64px; }
  .briefing-body { padding: 56px 24px; }
  .release-meta { flex-direction: column; align-items: flex-start; }
  .stats-grid, .join-grid { grid-template-columns: 1fr; }
  .own-table td:first-child { width: auto; }
}

